                  steps: ["Tom: Sol# menor (relativo de Si maior), na afinação padrão. A penta é a de Sol# menor: Sol#, Si, Dó#, Ré# e Fá#. Tudo fica no shape 1, nas casas 3 a 7.", "Abertura: o Fá# da 2ª corda, casa 7, sobe um tom até o Sol# (a tônica) e volta. Depois, o Ré# da 2ª corda, casa 4.", "O Lá# da 3ª corda, casa 3, não é da penta: é a 2ª de Sol# menor, uma passagem para o Sol# da 4ª corda, casa 6.", "O Sol# da 4ª corda, casa 6, fica soando por quatro tempos e meio, com vibrato. É a 3ª do acorde de Mi (que entra no meio do compasso) e a 5ª do Dó# menor que vem depois.", "Segunda frase: o Sol# da 1ª corda, casa 4, vai e volta ao Fá# da 2ª corda, casa 7, que também sobe um tom até o Sol#. O Lá# da 1ª corda, casa 6, entra rápido, de passagem.", "Desce até o Si da 3ª corda, casa 4, passando pelo Mi da 2ª corda, casa 5, no Dó# menor: o Mi não é da penta, mas é a 3ª desse acorde.", "Fecho: notas fracas alternando Fá# e Mi na 2ª corda, e o Mi longo no fim, sobre o acorde de Mi, em que ele é a tônica.", "A base segue a gravação: Sol# menor e Mi no mesmo compasso; no compasso seguinte, Dó# menor, depois Mi e Fá#."],
