                  steps: ["Afinação: pela tab, a guitarra está meio tom abaixo e o solo soa em Sol# maior. Com afinação normal, as mesmas casas soam em Lá maior, como aqui.", "Tom: Lá maior. O solo usa a penta de Lá menor (Lá, Dó, Ré, Mi, Sol), a do blues, sobre o acorde de Lá maior. Shape 1, casas 5 a 7, nas cordas agudas.", "O grupo de três: o Ré da 3ª corda, casa 7, sobe um tom até o Mi (4ª à 5ª), e o Mi da 2ª corda, casa 5, toca duas vezes. Cada grupo dura três colcheias e o compasso tem quatro tempos: o bend cai em lugares diferentes do compasso. No segundo grupo, o Lá da 1ª corda, casa 5, entra junto com o Mi, bem de leve (nota fantasma na tab).", "Nota fora da penta no fim do compasso 65: o Fá# da 2ª corda, casa 7, junto com o Ré da 3ª corda, casa 7, num bend duplo de cerca de três quartos de tom (no exemplo, meio tom). O Fá# é a 6ª de Lá, da escala maior.", "Depois, Dó, Lá, Ré e Dó, na 3ª e na 4ª cordas (casas 5 e 7), ainda no shape 1.", "O fim da parte vai ao grave: Fá# da 4ª corda, casa 4, com um bend de meio tom, Mi (casa 2) e Dó da 5ª corda, casa 3, com outro bend de meio tom, e o Lá solto. Notas fora da penta: o Fá# e o Dó#, que o bend do Dó alcança. O Dó# é a 3ª maior de Lá.", "A base segue a gravação: Ré no compasso de entrada, e Lá nos quatro seguintes. O baixo da gravação caminha Lá, Sol e Fá# no fim de alguns compassos; a base mantém o Lá."],
