                  steps: ["Tom: Lá menor. Os acordes (Fá, Dó, Ré menor e Sol) são todos do tom de Dó maior, o relativo de Lá menor, então a penta de Lá menor, que tem as mesmas notas da de Dó maior, serve nos quatro.", "A frase de abertura, no shape 3 (casas 10 a 12): Lá na 5ª corda, casa 12, com um deslize curto vindo da casa 10; Dó na 4ª corda, casa 10; Lá na 2ª corda, casa 10 (a tab põe o Fá da 3ª corda, casa 10, junto; aqui só o Lá); e Ré na 4ª corda, casa 12, com vibrato. Sobre o Fá, o Lá é a 3ª do acorde e o Dó é a 5ª.", "Os ligados: Sol e Fá na 5ª corda, casas 10 e 8, alternados com o dedo da mão esquerda, sem palhetar de novo. Nota fora da penta: o Fá, que é a 4ª de Dó e, no compasso seguinte, a 3ª de Ré menor. É nota do acorde, não do desenho.", "O fim da frase vai ao grave: Ré na 6ª corda, casa 10, e depois Sol e Lá nas casas 3 e 5 da mesma corda (shape 5, uma oitava abaixo). Nota fora da penta: o Fá da casa 1, a 3ª de Ré menor e, sobre o Sol, a 7ª menor, de passagem. Fecha no Ré da 5ª corda, casa 5.", "A segunda frase repete a abertura e alterna Lá (5ª corda, casa 12) e Dó (4ª corda, casa 10) em semicolcheias, antes de segurar o Ré.", "Depois, o shape 4 (casas 12 a 15): Sol e Lá na 3ª corda, Dó e Ré na 2ª corda, o Ré com vibrato. Nota fora da penta no fim: uma dupla de notas na casa 16 das 6ª e 5ª cordas (Sol# e Dó#), de passagem, num deslize que cai no Lá da casa 12 da frase seguinte.", "A base segue a gravação: Fá e Dó num compasso, Ré menor e Sol no outro, duas vezes."],
