                  steps: ["Tom: Lá menor. Shape 3 (casas 10 a 13), na 2ª e na 3ª corda, e depois a 1ª corda, nas casas 10 a 15.", "A figura: bend de um tom do Sol ao Lá na 3ª corda, casa 12, e depois Lá (2ª corda, casa 10), Dó (2ª corda, casa 13) e Lá. O Lá do bend e o da 2ª corda têm a mesma altura: o bend chega na nota que a 2ª corda toca em seguida. A figura dura três semicolcheias, mas o compasso tem dezesseis semicolcheias: ela se repete sem bater com o tempo, como o rolo da parte 2.", "Ela ocupa os dois compassos de Fá. No compasso seguinte, sobre o Dó, o Ré e o Fá da 1ª corda (casas 10 e 13) levam ao Sol da casa 15, repetido, com o Fá antes de cada Sol. Nota fora da penta: o Fá, que sobre o Dó é a 4ª, de passagem.", "A figura volta sobre o Lá menor, com um Fá de passagem no começo, e fecha num bend de um tom do Sol ao Lá, que volta, e no Fá da 3ª corda, casa 10. O Fá, fora da penta, é a 3ª de Ré menor e prepara o fim.", "O solo fecha no Ré da 4ª corda, casa 12, uma nota longa, de vibrato.", "A base segue a gravação: Fá nos dois primeiros compassos, Dó, Lá menor e Dó, e Ré no último. O Ré da gravação é só a nota do baixo: a base toca Ré menor."],
