                  steps: ["Tom: Ré menor. A música está em Fá maior, e a penta é a do relativo menor: Ré, Fá, Sol, Lá e Dó. A mão fica no shape 1 (casas 10 a 13).", "O Sol da 3ª corda, casa 12, é a 4ª de Ré. A tab marca um bend de um tom: o Sol sobe até o Lá (5ª) e fica ali, com vibrato. A anacruse, no fim do 1º compasso, já entra com esse bend.", "No 3º compasso da parte, o Sol vem em tercinas de semínima, ora reto, ora dobrado até o Lá. O que segura a frase é o ritmo da repetição.", "Nota fora da penta: o Si da 2ª corda, casa 12, curto, entre dois Sol. É a 6ª de Ré, nota de passagem.", "Acorde: no 1º compasso, o baixo toca Lá, e a base toca Lá menor. Dali em diante o baixo toca o riff em Ré, e a base toca Ré menor."],
