                  steps: ["Tom: Ré menor, na região do shape 5 (casas 7 a 10 nas cordas 3 e 4). O Ré da 3ª corda, casa 7, é a tônica e o ponto de chegada: o solo sai dele e volta para ele, com notas longas no 2º e no 4º compasso da parte.", "Notas fora da penta, todas perto do Ré: o Mi (3ª corda, casa 9) e o Si (4ª corda, casa 9) são a 2ª e a 6ª de Ré, de passagem; o Sol# (2ª corda, casa 9) é a 5ª diminuta, a nota de blues; e o Fá# (3ª corda, casa 11) é a 3ª maior de Ré.", "Bends: o Mi sobe meio tom até o Fá (3ª menor) e volta; o Sol# sobe meio tom até o Lá (5ª). No 5º compasso da parte, o Fá# sobe um tom até o Sol#; no 6º, o Fá (casa 10) sobe um tom até o Sol.", "Acorde: do 1º ao 5º compasso da parte, o baixo toca o riff em Ré, e a base toca Ré menor; no 6º, o baixo passa ao Sol, e a base toca Sol menor. O baixo não toca a 3ª do Ré, e o solo usa as duas: o Fá (menor) e o Fá# (maior)."],
