                  intro: "O solo final de Free Bird tem 156 compassos a 150 bpm, divididos aqui em seis partes. A parte 1, com 32 compassos, abre com bends de um tom na 2ª corda, casa 18, no shape 1 de Sol menor uma oitava acima da posição de base (casas 15 a 18), e passa para sequências repetidas de três e de quatro notas.",
                  steps: ["Tom: Sol menor, penta de Sol menor (Sol, Sib, Dó, Ré, Fá). A gravação está em Sol maior e o solo usa a penta de Sol menor sobre os acordes de Sol, Sib e Dó. Tudo no shape 1, casas 15 a 18, nas cordas 1 a 5.", "Compassos 1 a 8: o Fá da 2ª corda, casa 18, dobra um tom até o Sol (7ª menor à tônica), com o Sol da 1ª corda, casa 15, o Ré da 2ª corda, casa 15, e o Sib da 1ª corda, casa 18, de apoio. Nos compassos 9 a 12, o Fá dobrado e o Sib da 1ª corda alternam, com vibrato.", "Compassos 13 a 16: grupos de três notas repetidos, 15 notas por compasso: Fá (com bend de um tom), Ré e Fá.", "Compassos 17 a 20: grupos de quatro notas: Fá, Ré (ligado), Dó (3ª corda, casa 17) e Ré. Nos compassos 20 a 22: Sib (3ª corda, casa 15), Sol e Fá (4ª corda, casas 17 e 15).", "Compassos 22 a 28: o Dó da 3ª corda, casa 17, dobra um tom até o Ré (4ª à 5ª) e alterna com o Fá da 2ª corda, casa 18. Compassos 28 a 32: grupos de quatro notas, Sib (3ª corda, casa 15), Sol e Fá (4ª corda, casas 17 e 15) e Ré (5ª corda, casa 17).", "Sem nota fora da penta. O Fá soa como 7ª menor sobre o Sol, 5ª sobre o Sib e 4ª sobre o Dó: é por isso que ele aguenta ficar repetido enquanto o acorde muda.", "A base segue a gravação, com o Sol maior tocado como Sol menor: Sol, Sib, Dó e Dó, seis vezes, com Fá no fim dos Dó dos compassos 12 e 20 e Ré menor e Fá no compasso 24. Nos compassos 25 a 32: Sol; Fá e Sib; Sol e Dó; Sol e Sib; Sol; Fá; Dó; Dó."],
