                  intro: "A parte 2, com 28 compassos, continua nos grupos de quatro notas, passa ao bend do Dó e, no compasso 9, desce uma oitava: o mesmo desenho de bends do Fá ao Sol, agora no shape 1 das casas 3 a 6, e depois no shape 2, com bends de um tom e meio.",
                  steps: ["Tom: Sol menor, penta de Sol menor (Sol, Sib, Dó, Ré, Fá). A gravação está em Sol maior e o solo usa a penta de Sol menor sobre os acordes de Sol, Sib e Dó. Compassos 1 a 8 no shape 1 das casas 15 a 17; 9 a 28, no shape 1 baixo (casas 3 a 6) e no shape 2 (casas 5 a 8).", "Compassos 1 a 5: grupos de quatro notas, Sol (4ª corda, casa 17, com vibrato), Fá (casa 15), Ré (5ª corda, casa 17) e Fá. Compassos 5 a 8: o Dó da 3ª corda, casa 17, dobra um tom, com Sib, Sol e Fá em volta; no compasso 8, o Dó dobra e solta, de um tom e de meio tom.", "Compassos 9 a 16: a frase de bends do Fá ao Sol da parte 1, uma oitava abaixo: Sol (1ª corda, casa 3), Fá (2ª corda, casa 6, que dobra um tom), Ré (2ª corda, casa 3) e Sib (1ª corda, casa 6).", "Compassos 17 a 24: o Sol da 2ª corda, casa 8, com vibrato e repetido, e o Fá da casa 6. Nos compassos 20 e 24 o Sol dobra um tom e meio, até o Sib, quatro vezes, sobre o Dó (onde o Sib é a 7ª menor).", "Compassos 25 a 28: Sol (1ª corda, casa 3) e Mi (2ª corda, casa 5), com o Lá da 1ª corda, casa 5, entre eles. Mi e Lá são fora da penta de Sol menor: são da penta de Sol maior (a 6ª e a 2ª de Sol), passagem curta para voltar ao Sol.", "No compasso 9, o Fá# (4ª corda, casa 4) e o Si (3ª corda, casa 4) aparecem de passagem, e o Si de novo no 12: são a 7ª maior e a 3ª de Sol, fora da penta.", "A base segue a gravação, com o Sol maior tocado como Sol menor: Sol, Sib, Dó e Dó, com Fá no fim de vários compassos; nos compassos 15 e 19 o Sib continua por mais um compasso; no compasso 28, Fá."],
