                  intro: "A parte 3, a mais rápida do solo, com 32 compassos, abre com um desenho de seis notas repetido nas casas 3 a 6, volta ao grupo de quatro notas da parte 1 por oito compassos e termina em Mi, Sol e Lá, nas casas 12 a 15.",
                  steps: ["Tom: Sol menor, penta de Sol menor (Sol, Sib, Dó, Ré, Fá). A gravação está em Sol maior e o solo usa a penta de Sol menor sobre os acordes de Sol, Sib e Dó. Casas 3 a 6 (compassos 1 a 4), 15 a 18 (5 a 24) e 12 a 15 (25 a 32).", "Compassos 1 a 4: Sib (1ª corda, casa 6), Sol (casa 3), Lá (casa 5, fora da penta, de passagem), Sol, Fá (2ª corda, casa 6) e Sol, repetido em semicolcheias, 16 notas por compasso, o trecho mais rápido do solo.", "Compassos 5 a 12: o grupo de quatro notas Fá (2ª corda, casa 18), Ré (casa 15, ligado), Dó (3ª corda, casa 17) e Sol (1ª corda, casa 15), repetido. Compassos 13 e 14: Sib (1ª corda, casa 18), Sol e Ré, em grupos de três.", "Compassos 15 e 16: grupos de três notas, Fá (2ª corda, casa 18), Ré (casa 15, ligado) e Sib (3ª corda, casa 15); o Dó# da 3ª corda, casa 18, no início, é fora da penta, de passagem.", "Compassos 17 e 18: o Fá da 2ª corda, casa 18, dobra um tom e solta, várias vezes. Compassos 18 a 20: o Sol da 1ª corda, casa 15, repetido em semicolcheias, com um bend do Dó (3ª corda, casa 17) no compasso 19. No fim do 20, o Mi da 2ª corda, casa 17 (fora da penta, de passagem) e o Ré.", "Compassos 21 a 24: grupos de quatro notas, Sol, Fá, Ré (5ª corda) e Sib, no shape 1 das casas 15 a 17.", "Compassos 25 a 32: Sol (3ª corda, casa 12), Mi (4ª corda, casa 14) e Lá (3ª corda, casa 14), com o Lá dobrado um tom até o Si nos compassos 27 e 28. Mi, Lá e Si são da penta de Sol maior, fora da de Sol menor; o Sib e o Fá voltam no fim, e no compasso 32 o Sib dobra um tom até o Dó.", "A base segue a gravação, com o Sol maior tocado como Sol menor: Sol, Fá, Sol e (Sib, Dó), quatro vezes; depois Sol, Sib e Dó, com Sol no compasso 20, Fá no 24 e Sib e Fá no 28."],
