                  steps: ["Tom: Sol menor, penta de Sol menor (Sol, Sib, Dó, Ré, Fá). A gravação está em Sol maior e o solo usa a penta de Sol menor sobre os acordes de Sol, Sib e Dó. Casas 12 a 15 (compassos 1 a 14), 15 a 18 (15 a 24) e 22 (25 a 32).", "Compassos 1 a 14: Sol (3ª corda, casa 12), Mi (4ª corda, casa 14) e Lá (3ª corda, casa 14), com o Ré da 2ª corda, casa 15, repetido. Mi e Lá são fora da penta de Sol menor e são da penta de Sol maior: a 6ª e a 2ª de Sol.", "O Lá da 3ª corda, casa 14, dobra um tom até o Si (3ª maior de Sol) nos compassos 1, 3, 9 e 10.", "Compassos 15 a 18: o Ré da 2ª corda, casa 15, repetido, e o Fá (casa 18). Compassos 19 e 20: o Dó (3ª corda, casa 17) dobra um tom, com vibrato, alternando com o Fá. Compassos 21 a 24: o Fá dobra um tom e alterna com o Sib da 1ª corda, casa 18.", "Compassos 25 a 32: o Lá da 2ª corda, casa 22, dobra um tom até o Si e alterna com o Ré da 1ª corda, casa 22; no compasso 31, o Ré repetido, 16 vezes. É a nota mais aguda do solo; o Lá é fora da penta, e o Si de chegada é a 3ª maior de Sol.", "A base segue a gravação, com o Sol maior tocado como Sol menor: Sol, Sib, Dó e Dó, sete vezes, com Fá no compasso 16; Ré menor e Fá nos compassos 29 e 30, Sol no 31 e Sib e Fá no 32."],
