                  steps: ["Tom: Sol menor, penta de Sol menor (Sol, Sib, Dó, Ré, Fá). A gravação está em Sol maior e o solo usa a penta de Sol menor sobre os acordes de Sol, Sib e Dó. Casas 12 a 17 (compassos 1 a 8), 7 a 14 nas cordas 5 e 6 (9 e 10) e 12 a 18 (11 a 16).", "Compassos 1 a 5: Sol (3ª corda, casa 12), Lá (casa 14, ligado) e Mi (4ª corda, casa 14), e o Lá dobrado um tom até o Si e repetido, alternando com o Ré da 2ª corda, casa 15. Lá, Mi e Si são fora da penta de Sol menor.", "Compassos 6 e 7: o Mi da 2ª corda, casa 17 (fora da penta), e o Ré (casa 15), com slides, e a descida Ré, Dó (casa 13) e Si (casa 12, fora da penta), que fecha o desenho.", "Compassos 9 e 10: uma frase nas cordas 5 e 6, casas 7 a 14: Sol (5ª corda, casa 10), Si (6ª corda, casa 7), Ré (casa 10), Mi (casa 12) e Lá (5ª corda, casa 12). Si, Mi e Lá são fora da penta.", "Compassos 11 e 12: o Lá dobra um tom, até o Si, e, no compasso 12, um tom e meio, até o Dó.", "Compassos 13 e 14: o Fá dobra um tom e alterna com o Sol da 1ª corda, casa 15; o Dó da 3ª corda, casa 17, dobra um tom. Compassos 15 e 16: Sib, Sol, Dó e Fá, nas cordas 3 e 4, casas 15 a 17; o solo termina no Sib da 3ª corda, casa 15, dobrado meio tom até o Si.", "A base segue a gravação, com o Sol maior tocado como Sol menor: compassos 1 a 4, Sol, Sib, Dó, Sib; 5 a 8, Sol, Sib, Dó, Fá; 9 a 12, Sol, Sib, Dó e Sib, Sib e Fá; 13 a 16, Sol, Sib, Dó, Sib."],
