                  intro: "O solo final de November Rain é uma frase de cinco compassos que volta seis vezes. Abre com um bend de meio tom, do Si ao Dó, no registro agudo, e fecha numa corrida de semicolcheias. Esta parte traz a frase duas vezes: a segunda, com a corrida mais rápida.",
                  steps: ["Afinação: pela tab, a guitarra está meio tom abaixo e o solo soa em Si menor. Com afinação normal, as mesmas casas soam em Dó menor, como aqui.", "Tom: Dó menor, penta de Dó, Mib, Fá, Sol e Sib. A frase abre no shape 5 (1ª corda, casas 18 a 20) e fecha no shape 4 (casas 15 a 18).", "O Si da 1ª corda, casa 19, sobe meio tom até o Dó, a tônica: o Si, a sensível, não é da penta, e o bend o leva à nota que resolve. Depois o Dó da casa 20, longo, recebe um bend de um tom até o Ré, a 9ª, também fora da penta.", "A frase fecha no shape 4: Sol (1ª corda, casa 15), Mib (2ª corda, casa 16) e Sol. No compasso seguinte, o Láb da casa 16, com vibrato, e ligados rápidos entre Sol, Láb e Fá (1ª corda, casas 15, 16 e 13). Sobre o acorde de Láb, o Láb é a tônica: nota fora da penta, mas do acorde.", "Os dois compassos seguintes são semicolcheias alternadas entre Láb, Sol, Fá e Mib (1ª e 2ª cordas, casas 13 a 16). O Ré da 2ª corda, casa 15, a 9ª, aparece de passagem; no compasso seguinte, dois bends de meio tom o levam ao Mib, a 3ª menor. O compasso termina no Si da 3ª corda, casa 16, a sensível que prepara a frase seguinte.", "Na segunda vez, o fim muda: a corrida fica mais rápida, com seis a oito notas por tempo, pelas três cordas agudas, das casas 9 a 18, e fecha no Ré da 4ª corda, casa 12.", "A base segue a gravação: Dó menor e Sol menor, Fá e Mib, Láb e Sib, Dó menor em dois compassos, duas vezes. A tab do piano traz o Sol sem a 3ª; a base toca Sol menor. O Fá é maior na gravação, fora do tom de Dó menor; a base toca Fá menor."],
