                  steps: ["Tom: Lá menor. Os três primeiros compassos ficam no shape 1, na casa 5; os dois últimos, nos shapes 3 e 4, das casas 10 a 15.", "Começa com o mesmo bend do Ré (4ª) ao Mi (5ª) da abertura, e um bend curto no Ré, de menos de meio tom: o choro do blues, que não chega em nota nenhuma da escala.", "O Sol da 3ª corda solta é a mesma nota da 4ª corda, casa 5: continua no shape 1.", "Nota fora da penta: o Fá (6ª menor de Lá menor) aparece três vezes. Na 5ª corda, casa 8, e na 1ª corda, casa 13, o acorde é Fá: é a tônica dele. Na 3ª corda, casa 10, é só passagem rápida entre o Dó e o Ré.", "A virada: o slide na 5ª corda até a casa 12 leva a mão para o shape 4. Daí a frase sobe até o bend do Ré ao Mi na 2ª corda, casa 15, e o bend do Sol (7ª menor) ao Lá (tônica) na 1ª corda, casa 15."],
